import{c as s,Q as a,j as o,m as t}from"./chunks/framework.BvWD_EvC.js";const k=JSON.parse('{"title":"API Keys","description":"","frontmatter":{},"headers":[],"relativePath":"guide/api-keys.md","filePath":"guide/api-keys.md","lastUpdated":1792008388000}'),i={name:"guide/api-keys.md"};function n(r,e,l,d,p,c){return a(),o("div",null,[...e[0]||(e[0]=[t(`<h1 id="api-keys" tabindex="-1">API Keys <a class="header-anchor" href="#api-keys" aria-label="Permalink to &quot;API Keys&quot;">​</a></h1><p>Some external sources require API keys. All are optional: Open Library, BnF, Inventaire.io, and the Library of Congress need no key at all, so LibrisLog works out of the box.</p><p>Sources without a key can be switched off individually, see <a href="/next/guide/configuration.html">Configuration</a>.</p><div class="warning custom-block"><p class="custom-block-title">Both keyed sources are off in <code>.env.example</code></p><p>A key alone is not enough to make a source answer, and leaving a source switched on without its key is just noise. <code>.env.example</code> therefore ships <code>HARDCOVER_IMPORT_SEARCH_ENABLED=false</code> and <code>GOOGLE_BOOKS_IMPORT_SEARCH_ENABLED=false</code>. Set the credential and flip the matching switch to <code>true</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">GOOGLE_BOOKS_API_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">your-key</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">GOOGLE_BOOKS_IMPORT_SEARCH_ENABLED</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">true</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">HARDCOVER_APP_API_TOKEN</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">your-token</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">HARDCOVER_IMPORT_SEARCH_ENABLED</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">true</span></span></code></pre></div><p>The built-in default for both switches is <code>true</code>, so an existing <code>.env</code> that does not mention them keeps working after an upgrade. If you leave a source on without its credential, it is listed in the search progress as skipped and no request is sent.</p></div><h2 id="google-books-api" tabindex="-1">Google Books API <a class="header-anchor" href="#google-books-api" aria-label="Permalink to &quot;Google Books API&quot;">​</a></h2><p>Enables Google Books as a fallback search source and improves cover resolution. Remember to also set <code>GOOGLE_BOOKS_IMPORT_SEARCH_ENABLED=true</code>.</p><ol><li>Go to the <a href="https://console.cloud.google.com" target="_blank" rel="noreferrer">Google Cloud Console</a></li><li>Create a new project or select an existing one</li><li>Navigate to <strong>APIs &amp; Services</strong> → <strong>Library</strong></li><li>Search for &quot;Books API&quot; and enable it</li><li>Go to <strong>APIs &amp; Services</strong> → <strong>Credentials</strong></li><li>Click <strong>Create Credentials</strong> → <strong>API Key</strong></li><li>Copy the key and set it as <code>GOOGLE_BOOKS_API_KEY</code> in your <code>.env</code></li></ol><blockquote><p><strong>Note</strong>: Google Books API has usage limits. For most personal use, the free tier is sufficient. See <a href="https://developers.google.com/books" target="_blank" rel="noreferrer">Google&#39;s documentation</a> for quota details.</p></blockquote><h2 id="hardcover-api" tabindex="-1">Hardcover API <a class="header-anchor" href="#hardcover-api" aria-label="Permalink to &quot;Hardcover API&quot;">​</a></h2><p>Enables Hardcover.app as an additional search source. Remember to also set <code>HARDCOVER_IMPORT_SEARCH_ENABLED=true</code>.</p><ol><li>Sign in to <a href="https://hardcover.app" target="_blank" rel="noreferrer">hardcover.app</a></li><li>Go to your profile → <strong>Settings</strong> → <strong>API</strong></li><li>Create a new API token</li><li>Copy the token and set it as <code>HARDCOVER_APP_API_TOKEN</code> in your <code>.env</code></li></ol>`,11)])])}const g=s(i,[["render",n]]);export{k as __pageData,g as default};
